        { when: pair("Residual rank 통과·sensor coverage 실패", "Residual rank passes but sensor coverage fails"), then: pair("관측 hardware·protocol을 먼저 고치고 model 확장을 중단", "Fix observation hardware or protocol before expanding the model") },
        { when: pair("g·z·h·m 모두 독립 gate 통과", "g, z, h, and m all pass independent gates"), then: pair("선언한 process 범위에서 state-updating twin으로 승격", "Promote to a state-updating twin within the declared process domain") }
